package com.hallo.logistics.driver
import org.junit.Assert.*
import org.junit.Test
class DriverAccessPolicyTest { @Test fun blocksEveryOtherRole(){listOf("customer","partner","admin","ceo").forEach{assertEquals(DriverAccess.FORBIDDEN,DriverAccessPolicy.resolve(it,"approved"))}}; @Test fun pinIsExactlySixDigits(){assertTrue(DriverAccessPolicy.validSignupPin("123456"));assertFalse(DriverAccessPolicy.validSignupPin("12345"));assertFalse(DriverAccessPolicy.validSignupPin("12345a"))};@Test fun authErrorsNeverExposeRequestHeaders(){val raw="invalid_credentials URL: https://project.supabase.co/auth/v1/token Headers: Authorization=[Bearer sb_publishable_example], apikey=[sb_publishable_example]";val safe=DriverErrorPolicy.safeMessage(RuntimeException(raw));assertEquals("Email or password is incorrect",safe);assertFalse(safe.contains("https://"));assertFalse(safe.contains("apikey"));assertFalse(safe.contains("Bearer"))} }
